//! Every case of `models_text.jsonl`, `models_text_unicode.jsonl` and
//! `models_text_platform.jsonl` against `models_text`: the slug, the file
//! name, the summary line, the truncation heuristic and the snippets,
//! with the two digest sweeps regenerated by their rules.

mod common;

use bettermemory_core::datetime::DateTime;
use bettermemory_core::models_text::{
    build_filename, first_summary_line, looks_truncated, make_slug, snippet_for, snippet_window,
    truncate_at_word, word_ending_at, ABBREVIATIONS, BODY_TERMINALS, SLUG_MAX_CHARS,
    SLUG_MAX_WORDS, SNIPPET_MAX_CHARS, SUMMARY_MAX_CHARS,
};
use bettermemory_core::pyvalue::PyStr;
use bettermemory_core::unicode;
use common::jsonl;
use common::parity::Ledger;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

fn hexed(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn text(v: &Value) -> PyStr {
    if let Some(s) = v.as_str() {
        return unicode::cps(s);
    }
    if let Some(cps) = v.get("cps") {
        return common::cps_of(cps);
    }
    let mut out = Vec::new();
    for pair in v["rep"].as_array().expect("rep") {
        let piece = unicode::cps(pair[0].as_str().expect("piece"));
        for _ in 0..pair[1].as_u64().expect("count") {
            out.extend_from_slice(&piece);
        }
    }
    out
}

fn out(a: &[u32]) -> Value {
    if a.len() > 120 {
        let mut h = Sha256::new();
        for &c in a {
            h.update(c.to_be_bytes());
        }
        return json!({"n": a.len(), "sha": hexed(&h.finalize())});
    }
    if a.iter().any(|c| (0xD800..=0xDFFF).contains(c)) {
        return json!({ "cps": a });
    }
    json!(unicode::to_string(a).expect("text"))
}

fn int(case: &Value, key: &str) -> i64 {
    case[key].as_i64().expect(key)
}

fn answer(case: &Value) -> Value {
    let t = text(&case["t"]);
    match case["k"].as_str().expect("k") {
        "slug" => out(&make_slug(&t, int(case, "w"), int(case, "c"))),
        "file" => {
            let d = &case["d"];
            let dt = DateTime {
                year: d[0].as_i64().expect("year") as i32,
                month: d[1].as_u64().expect("month") as u32,
                day: d[2].as_u64().expect("day") as u32,
                hour: 0,
                minute: 0,
                second: 0,
                microsecond: 0,
                offset_us: None,
            };
            out(&build_filename(&dt, &t))
        }
        "word" => match word_ending_at(&t, int(case, "e")) {
            Some(w) => out(&w),
            None => json!({"err": "IndexError"}),
        },
        "trunc" => json!(looks_truncated(&t)),
        "summ" => out(&first_summary_line(&t, int(case, "m"))),
        "snip" => out(&snippet_for(&t, int(case, "m"))),
        "win" => out(&snippet_window(&t, int(case, "s"), int(case, "m"))),
        "taw" => out(&truncate_at_word(&t, int(case, "m"))),
        other => panic!("unknown kind {other}"),
    }
}

enum Answer {
    Text(PyStr),
    Flag(bool),
}

fn feed(h: &mut Sha256, answers: &[Answer]) {
    for a in answers {
        match a {
            Answer::Flag(b) => h.update(u32::from(*b).to_be_bytes()),
            Answer::Text(t) => {
                for &c in t {
                    h.update(c.to_be_bytes());
                }
            }
        }
        h.update([0xFF; 4]);
    }
}

const MASK: u128 = (1 << 64) - 1;

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = ((u128::from(z ^ (z >> 30)) * 0xBF58_476D_1CE4_E5B9) & MASK) as u64;
        z = ((u128::from(z ^ (z >> 27)) * 0x94D0_49BB_1331_11EB) & MASK) as u64;
        z ^ (z >> 31)
    }

    fn below(&mut self, n: u64) -> i64 {
        (self.next() % n) as i64
    }
}

const PIECES: [&str; 42] = [
    "a",
    "b",
    "word",
    "Zeta",
    " ",
    " ",
    "  ",
    "\n",
    "\t",
    "\r",
    ".",
    ". ",
    "!",
    "?",
    "-",
    "--",
    ",",
    ";",
    ":",
    "_",
    "/",
    "|",
    "0",
    "7",
    "2024-05-07",
    "2026-01-02T10:30",
    "T12:30:45Z",
    "+05:30",
    "-0800",
    "e.g.",
    "i.e.",
    "Mr.",
    "U.S.",
    "etc.",
    "vs.",
    "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
    "user.name",
    "1.0.2",
    ")",
    "\"",
    "`",
    "*",
];

/// The random sweep: `_random_case` and `_random_answers`.
fn random_sweep(seed: u64, count: usize) -> String {
    let mut rng = Rng(seed);
    let mut h = Sha256::new();
    for _ in 0..count {
        let pieces = rng.below(80);
        let mut t = Vec::new();
        for _ in 0..pieces {
            t.extend(unicode::cps(
                PIECES[rng.below(PIECES.len() as u64) as usize],
            ));
        }
        let w = rng.below(13) - 3;
        let c = rng.below(250) - 5;
        let s = rng.below(300) - 2;
        feed(
            &mut h,
            &[
                Answer::Text(make_slug(&t, w, c)),
                Answer::Flag(looks_truncated(&t)),
                Answer::Text(first_summary_line(&t, c)),
                Answer::Text(snippet_for(&t, c)),
                Answer::Text(snippet_window(&t, s, c)),
                Answer::Text(truncate_at_word(&t, c)),
            ],
        );
    }
    hexed(&h.finalize())
}

fn cat(parts: &[&[u32]]) -> PyStr {
    parts.concat()
}

/// The every-code-point sweep: `_every_answers`.
fn every_sweep() -> String {
    let mut h = Sha256::new();
    let date = unicode::cps("2024-01-02");
    let date0 = unicode::cps("2024-01-0");
    let words = unicode::cps(&"word ".repeat(50));
    let [ab_, cd, sx, xy, ab, vs, two, abdot] =
        ["ab ", "cd", " x", "x\ny", "ab", "one vs", ". two", "ab."].map(unicode::cps);
    for cp in 0..0x11_0000u32 {
        let ch: &[u32] = &[cp];
        feed(
            &mut h,
            &[
                Answer::Text(make_slug(
                    &cat(&[&date, ch, &ab_, ch, &cd]),
                    SLUG_MAX_WORDS,
                    SLUG_MAX_CHARS,
                )),
                Answer::Text(make_slug(
                    &cat(&[&date0, ch, &sx]),
                    SLUG_MAX_WORDS,
                    SLUG_MAX_CHARS,
                )),
                Answer::Text(make_slug(
                    &cat(&[ch, &xy, ch]),
                    SLUG_MAX_WORDS,
                    SLUG_MAX_CHARS,
                )),
                Answer::Flag(looks_truncated(&cat(&[&ab, ch]))),
                Answer::Text(first_summary_line(
                    &cat(&[&vs, ch, &two]),
                    SUMMARY_MAX_CHARS,
                )),
                Answer::Text(first_summary_line(
                    &cat(&[&abdot, ch, &cd]),
                    SUMMARY_MAX_CHARS,
                )),
                Answer::Text(snippet_for(&cat(&[ch, &words, ch]), SNIPPET_MAX_CHARS)),
            ],
        );
    }
    hexed(&h.finalize())
}

fn sweep(case: &Value) -> Value {
    let mut got = case.clone();
    let count = case["count"].as_u64().expect("count") as usize;
    got["sha"] = json!(match case["rule"].as_str().expect("rule") {
        "random" => random_sweep(case["seed"].as_u64().expect("seed"), count),
        "every" => {
            assert_eq!(count, 0x11_0000);
            every_sweep()
        }
        other => panic!("unknown rule {other}"),
    });
    got
}

fn every_case(name: &str, test: &str) {
    let lines = jsonl(name);
    let header = &lines[0];
    if let Some(abbrevs) = header.get("abbreviations") {
        let mut ours: Vec<&str> = ABBREVIATIONS.to_vec();
        ours.sort_unstable();
        assert_eq!(*abbrevs, json!(ours));
        let mut terms: Vec<char> = BODY_TERMINALS.chars().collect();
        terms.sort_unstable();
        assert_eq!(header["terminals"], json!(terms.iter().collect::<String>()));
    }
    let in_file = header["cases"].as_u64().expect("cases") as usize;
    assert_eq!(in_file, lines.len() - 1, "{name}: header count");
    let mut ledger = Ledger::new(test, name);
    for (i, case) in lines[1..].iter().enumerate() {
        ledger.case(format!("case {i} ({})", case["k"]), || {
            if case["k"] == "sweep" {
                assert_eq!(sweep(case), *case, "{name} case {i}");
            } else {
                let mut got = case.clone();
                got["r"] = answer(case);
                assert_eq!(got, *case, "{name} case {i}");
            }
        });
    }
    ledger.finish(in_file);
}

#[test]
fn models_text_every_case() {
    every_case("models_text.jsonl", "models_text_every_case");
}

#[test]
fn models_text_unicode_every_case() {
    every_case(
        "models_text_unicode.jsonl",
        "models_text_unicode_every_case",
    );
}

#[test]
fn models_text_platform_every_case() {
    every_case(
        "models_text_platform.jsonl",
        "models_text_platform_every_case",
    );
}
